if(settingsWereReset){context().extensionSettings[NS]={...structuredClone(DEFAULTS),settingsSchema:SETTINGS_SCHEMA};try{localStorage.removeItem(NS+':connection-presets');}catch{}}
let settings=context().extensionSettings[NS]=Object.assign(structuredClone(DEFAULTS),settingsWereReset?{settingsSchema:SETTINGS_SCHEMA,attics:previousSettings.attics||{}}:previousSettings);
if(!settingsWereReset&&!previousSettings.filterMode){settings.filterMode=previousSettings.sourceTag?'include':previousSettings.excludeTags?'exclude':'off';settings.filterTags=previousSettings.sourceTag||previousSettings.excludeTags||'content';}
if(settings.basePrompt===OLD_BASE_PROMPT)settings.basePrompt=DEFAULTS.basePrompt;
if(settings.checkPrompt===OLD_CHECK_PROMPT)settings.checkPrompt=DEFAULTS.checkPrompt;
if(settings.preset){settings.promptEntries=[...(settings.promptEntries||[]),{id:crypto.randomUUID(),name:'旧版预设',content:settings.preset,enabled:true}];settings.preset='';}
settings.profiles??=[];if(!settings.profiles.some(p=>p.id===DEFAULT_PROFILE_ID)){settings.profiles.unshift({id:DEFAULT_PROFILE_ID,name:'默认设置',builtin:true,options:defaultProfileOptions()});context().saveSettingsDebounced();}if(settingsWereReset)context().saveSettingsDebounced();
if(!settingsWereReset&&previousSettings.filterVersion!==3)settings=migrateOptions({...settings,filterVersion:previousSettings.filterVersion});
const builtin=settings.profiles.find(p=>p.id===DEFAULT_PROFILE_ID);if(builtin){builtin.options=defaultProfileOptions();builtin.builtin=true;}
const globalSettings=context().extensionSettings[NS]=settings;
const globalKeys=new Set(['pluginEnabled','settingsSchema','repairSeparate','repairBaseUrl','repairModel','rememberKeys','summaryStream','checkStream','repairStream','checkSeparate','checkBaseUrl','checkModel','baseUrl','model','timeout','retries','outputTokens','attics','booksByCharacter','profiles']);
function contentSettings(value){return {settingsSchema:SETTINGS_SCHEMA,...Object.fromEntries(Object.keys(DEFAULTS).filter(k=>!globalKeys.has(k)&&!['worldBooks'].includes(k)).map(k=>[k,structuredClone(value[k]??DEFAULTS[k])]))};}
function migrateOptions(value){const mode=value.filterMode||'include';if(value.filterVersion===3)return {...value,filterMode:['off','combined'].includes(value.filterMode)?value.filterMode:'combined'};return {...value,filterVersion:3,filterMode:mode==='off'?'off':'combined',sourceTag:mode==='include'?(value.filterTags||value.sourceTag||''):'',excludeTags:mode==='exclude'?(value.filterTags||value.excludeTags||''):''};}
function loadChatSettings(){const saved=context().chatMetadata?.[NS]?.options;settings={...structuredClone(globalSettings),...migrateOptions(saved?.settingsSchema===SETTINGS_SCHEMA?saved:globalSettings)};settings.migrateNotice=settingsWereReset;settings=migrateOptions(settings);for(const k of globalKeys)settings[k]=globalSettings[k];settings.modes={...DEFAULTS.modes,...settings.modes};settings.sendFields={...DEFAULTS.sendFields,...settings.sendFields};settings.phasePriority={...DEFAULTS.phasePriority,...settings.phasePriority};}
loadChatSettings();settings.rememberKeys=true;
async function persistOptions(){await backup('修改聊天设置前');store().options=contentSettings(settings);await save();saveSettings();}

settings.modes={...DEFAULTS.modes,...settings.modes};
settings.sendFields={...DEFAULTS.sendFields,...settings.sendFields};
settings.attics??={};settings.booksByCharacter??={};
function selectedBooks(){try{return settings.booksByCharacter?.[characterKey()]||settings.worldBooks||[];}catch{return [];}}
let suppressKeyCapture=false,batchProcessing=false,batchRunning=false,appearanceDraft=null,autoMergeRunning=false,automaticTask=false,directSaving=false,requestedKind='short',batchTotal=0,batchPaused=false,autoPaused=false,logsMode='tasks',activeLogTask=null;
