function queueGenerated(generated){if(!draft){draft=generated;draftVersions=[];tab='draft';open();}else pendingDrafts.push({draft:generated,versions:[]});persistSession();}
function restorePendingDraft(){if(!draft&&pendingDrafts.length){const entry=pendingDrafts.shift();draft=entry.draft;draftVersions=entry.versions||[];}}
function pendingDraftsView(){return pendingDrafts.length?'<section class="smm-content"><b>待确认批次 · '+(pendingDrafts.length+(draft?1:0))+'份</b><p>各批草稿独立保存，不是同一份记忆的改写版本。</p>'+pendingDrafts.map((e,i)=>btn('pending-select','查看 '+h(e.draft.rangeLabel||floorLabel(e.draft.floors)),`data-index="${i}"`)).join('')+'</section>':'';}
function notify(message,error=false){let e=document.getElementById(NS+'-toast');if(!e){e=document.createElement('div');e.id=NS+'-toast';e.setAttribute('role','status');e.setAttribute('aria-live','polite');if(typeof e.showPopover==='function')e.setAttribute('popover','manual');document.body.append(e);}e.textContent=message;e.className=error?'error':'';e.hidden=false;const v=window.visualViewport;e.style.left=((v?.offsetLeft||0)+(v?.width||window.innerWidth)/2)+'px';e.style.top=((v?.offsetTop||0)+(v?.height||window.innerHeight)/2)+'px';if(typeof e.showPopover==='function'){try{e.showPopover();}catch{}}clearTimeout(e.timer);e.timer=setTimeout(()=>{if(typeof e.hidePopover==='function'){try{e.hidePopover();}catch{}}e.hidden=true;},error?9000:3500);}

const client=new ApiClient(()=>settings,log,context);
const checkClient=new ApiClient(()=>({...settings,baseUrl:settings.checkBaseUrl,model:settings.checkModel}),log,context);
const repairClient=new ApiClient(()=>({...settings,baseUrl:settings.repairBaseUrl,model:settings.repairModel}),log,context);
function keyStore(write=false){settings.rememberKeys=true;const key=NS+':api-keys';if(write){if(settings.rememberKeys!==false)localStorage.setItem(key,JSON.stringify({summary:client.key,check:checkClient.key,repair:repairClient.key}));else localStorage.removeItem(key);}else{try{const v=JSON.parse(localStorage.getItem(key)||'{}');client.key=v.summary||'';checkClient.key=v.check||'';repairClient.key=v.repair||'';}catch{}}}
keyStore();
try{keyProfiles=JSON.parse(localStorage.getItem(NS+':connection-presets')||'[]');}catch{}
function captureKeys(){for(const [id,c] of [['smm-key',client],['smm-check-key',checkClient],['smm-repair-key',repairClient]]){const el=panel?.querySelector('#'+id);if(el)c.key=el.value.trim();}}
function saveKeyProfiles(){localStorage.setItem(NS+':connection-presets',JSON.stringify(keyProfiles));}
function applyAppearance(){if(!panel)return;const hostStyle=getComputedStyle(document.body);const canvas=document.createElement('canvas'),paint=canvas.getContext('2d');paint.fillStyle='#202735';paint.fillRect(0,0,1,1);paint.fillStyle=hostStyle.getPropertyValue('--SmartThemeBlurTintColor').trim()||'#202735';paint.fillRect(0,0,1,1);const pixel=paint.getImageData(0,0,1,1).data,solid='rgb('+pixel[0]+','+pixel[1]+','+pixel[2]+')';document.documentElement.style.setProperty('--smm-tavern-bg',solid);document.documentElement.style.setProperty('--smm-tavern-font',hostStyle.fontFamily);const options={...settings,...pendingProfileOptions,...appearanceDraft};panel.dataset.theme=options.themePreset||'soft';document.documentElement.style.setProperty('--smm-dialog-bg',options.themePreset==='tavern'?solid:options.themePreset==='paper'?'#f2ede4':options.themePreset==='contrast'?'#121820':'#263244');document.documentElement.style.setProperty('--smm-dialog-ink',options.themePreset==='tavern'?(hostStyle.getPropertyValue('--SmartThemeBodyColor').trim()||'#e8edf4'):options.themePreset==='paper'?'#332f2b':'#f1f4f8');let el=document.getElementById('smm-custom-css');if(!el){el=document.createElement('style');el.id='smm-custom-css';document.head.append(el);}el.textContent=appearanceCss(options.appearance)+'\n'+fontCss(options.fontPreset)+'\n'+(options.customCss||'');}
function previewAppearance(target){if(!target.matches('[data-appearance],[data-setting="themePreset"],[data-setting="customCss"],[data-setting="fontPreset"]'))return;const options={...settings,...pendingProfileOptions,...appearanceDraft};if(target.type==='color'){const key=target.dataset.appearance.split('.').slice(0,-1).join('.')+'.colors';const toggle=panel.querySelector('[data-appearance="'+key+'"]');if(toggle)toggle.checked=true;}appearanceDraft={fontPreset:panel.querySelector('[data-setting=fontPreset]').value,appearance:readAppearance(panel,options.appearance),themePreset:panel.querySelector('[data-setting="themePreset"]').value,customCss:panel.querySelector('[data-setting="customCss"]').value};for(const out of panel.querySelectorAll('[data-appearance-output]')){const control=panel.querySelector('[data-appearance="'+out.dataset.appearanceOutput+'"]');if(control)out.textContent=control.value+'px';}applyAppearance();}

function styleButtons(){for(const b of panel.querySelectorAll('button')){if(!b.dataset.buttonLevel)b.dataset.buttonLevel=b.dataset.tab?'1':/^(edit|log-copy|entry-|minimize|close|settings-open)/.test(b.dataset.action||'')?'3':'2';if(/delete|clear|discard/.test(b.dataset.action||''))b.dataset.danger='true';}}
const taskProgress=createProgress(()=>{job?.controller.abort();client.cancel();checkClient.cancel();repairClient.cancel();},()=>{batchPaused=true;notify('本次调用结束后暂停后续批次');});
async function log(stage,data={}){const safe=JSON.parse(JSON.stringify(data,(_k,v)=>typeof v==='string'?[client.key,checkClient.key,repairClient.key,...keyProfiles.flatMap(p=>Object.values(p.keys||{}))].filter(Boolean).reduce((text,key)=>text.split(key).join('[密钥已隐藏]'),v):v));const memory=stage==='主模型记忆准备';const id=crypto.randomUUID();await record('logs',{id,chat:job?.chat||chatKey(),task:/确认保存|原生隐藏/.test(stage)?activeLogTask||job?.id||null:job?.id||activeLogTask||null,channel:memory?'memory':'tasks',sequence:++sequence,stage,data:safe,created:Date.now(),at:new Date().toISOString(),important:/模型返回|检查.*返回|保存|隐藏|解析失败|任务失败/.test(stage)||(stage==='API返回'&&['summary','check'].includes(data.kind))});return id;}
async function backup(reason){const key=chatKey();await record('snapshots',{id:crypto.randomUUID(),chat:key,reason,store:structuredClone(store()),attic:structuredClone(settings.attics),created:Date.now()});if(key!==chatKey())throw Error('备份期间聊天已切换，已停止操作');}
async function save(verify=false){const c=context(),key=chatKey();const revisionKey=NS+':revision:'+key;let known;try{known=JSON.parse(localStorage.getItem(revisionKey)||'null');}catch{}if(known&&known.writer!==windowId&&known.revision>Number(store().revision||0))throw Error('另一个标签页已更新记忆，请刷新后再操作；本次未覆盖');if(c.groupId)throw Error('初版暂不支持群聊写入，请使用单角色聊天');const expected=JSON.stringify(store());await c.saveMetadata();localStorage.setItem(revisionKey,JSON.stringify({writer:windowId,revision:store().revision||0,at:Date.now()}));if(key!==chatKey())throw Error('保存期间切换聊天，已停止后续操作');if(!verify)return;const ch=c.characters?.[c.characterId];const response=await fetch('/api/chats/get',{method:'POST',headers:c.getRequestHeaders(),body:JSON.stringify({ch_name:ch.name,file_name:c.chatId,avatar_url:ch.avatar})});if(!response.ok)throw Error('无法核验服务端保存，未继续隐藏');const saved=await response.json();if(key!==chatKey())throw Error('核验期间聊天已切换，已停止操作');if(JSON.stringify(saved[0]?.chat_metadata?.[NS])!==expected)throw Error('服务端保存核验未通过，未继续隐藏');}
function saveSettings(){for(const k of globalKeys)globalSettings[k]=settings[k];context().saveSettingsDebounced();}
function report(e){notify(String(e.message||e),true);log('操作失败',{message:String(e.message||e)}).catch(()=>{});}
function btn(action,text,extra=''){return `<button type="button" data-action="${action}" ${extra}>${text}</button>`;}
function input(key,label,type='text'){return `<label>${label}<input data-setting="${key}" type="${type}" value="${h(settings[key])}"></label>`;}
function check(key,label){return `<label class="smm-check"><input data-setting="${key}" type="checkbox" ${settings[key]?'checked':''}>${label}</label>`;}
function select(key,label,options){return `<label>${label}<select data-setting="${key}">${Object.entries(options).map(([k,v])=>`<option value="${k}" ${settings[key]===k?'selected':''}>${v}</option>`).join('')}</select></label>`;}
function area(key,label){return `<label>${label}<textarea data-setting="${key}" rows="5">${h(settings[key])}</textarea></label>`;}
function group(title,body){return `<details class="smm-group"><summary>${title}<small>点击展开或收起</small></summary>${body}</details>`;}
function ids(){return [...panel.querySelectorAll('[data-pick]:checked')].map(e=>e.dataset.pick);}
function card(m){const issues=[];return `<article class="smm-card" data-id="${h(m.id)}"><details class="smm-memory-details"><summary><input type="checkbox" aria-label="选择记忆" data-pick="${h(m.id)}"><span>${h(m.title)}</span>${m.kind==='long'&&!m.keywords?.length?'<strong class="smm-keyword-warning">缺少关键词，无法按词触发</strong>':''}<small>${h({fixed:'固定记忆',long:'长期记忆',short:'短期记忆'}[m.kind])} · ${summaryLevelLabel(m.level??0)} · ${h(m.rangeLabel||m.originLabel||(floorLabel(m.sources)+(m.sources?.length?'（历史来源跨度；原选区未记录）':'')))}</small></summary><header><b>${h(m.title)}</b><span class="smm-kind">${m.status==='active'?'发送候选':m.status==='index'?'仅保留来源索引':'已归档，不发送'}</span></header>${tab!=='draft'&&(m.validationWarnings||[]).length?'<aside class="smm-issues">'+m.validationWarnings.map(h).join('<br>')+'</aside>':''}<section class="smm-content"><h4>剧情摘要</h4><p>${h(m.summary)}</p></section>${Object.entries(m.details||{}).map(([k,v])=>`<section class="smm-content"><h4>${h(FIELDS[k]||k)} <small>${settings.sendFields[k]?'随记忆发送':'不发送'}</small></h4><p>${h(v)}</p></section>`).join('')}${tab!=='draft'&&(m.quoteChecks||[]).some(q=>!q.verified)?`<details class="smm-issues"><summary>待核对原话（不发送）</summary>${m.quoteChecks.filter(q=>!q.verified).map(q=>'<p>'+h(q.text)+'<br><small>'+h(q.reason)+'</small></p>').join('')}</details>`:''}<small>总结范围：${h(m.rangeLabel||m.originLabel||(floorLabel(m.sources)+(m.sources?.length?'（历史来源跨度；原选区未记录）':'')))} · ${summaryLevelLabel(m.level??0)}</small><details class="smm-group"><summary>${m.kind==='long'?'短版、关键词与核对依据':'核对依据与保留设置'}</summary>${m.kind==='long'?`<p>${h(m.brief)}</p><p>关键词：${h(m.keywords.join('、'))}</p>`:''}<p>原文核对节选（仅供用户核对，不发送）：${h(m.excerpt||'未保存：关闭了节选，或返回内容未通过逐字核对')}</p><label class="smm-check"><input type="checkbox" data-lock="${h(m.id)}" ${m.locked?'checked':''}>后续合并总结时必须保留本条事实（不代表每轮发送）</label></details>${issues.length?`<section class="smm-content smm-issues"><h4>AI检查意见（不发送）</h4><ul>${issues.map(i=>'<li>'+h(i.message)+'<br>建议：'+h(i.suggestion||'核对原文')+'</li>').join('')}</ul></section>`:''}<div class="smm-actions">${btn('edit','编辑',`data-id="${h(m.id)}"`)}${tab!=='draft'?btn('saved-check','AI检查',`data-id="${h(m.id)}"`):''}</div></details></article>`;}
function checkRawView(){if(tab!=='draft'||(!draft?.checked&&!draft?.reviewHistory))return '';const report=draft.checked?draft:draft.reviewHistory;return '<section class=\"smm-content\"><h4>AI检查原始回复</h4><details><summary>展开原始回复</summary><pre>'+h(report.checkRaw||'')+'</pre></details>'+(report.checkRepairRaw?'<details><summary>展开格式修复后的回复</summary><pre>'+h(report.checkRepairRaw)+'</pre></details>':'')+'</section>';}
