function settingsView(){return renderSettings({...settings,...pendingProfileOptions,...appearanceDraft,connectionPresets:keyProfiles},models,client.key,selectedBooks(),checkClient.key,checkModels,repairClient.key,repairModels);}

function intervalLabel(values){const sorted=[...new Set(values)].filter(Number.isInteger).sort((a,b)=>a-b),groups=[];for(const n of sorted){const last=groups.at(-1);if(last&&n===last[1]+1)last[1]=n;else groups.push([n,n]);}return groups.map(([a,b])=>`第${a}-${b}楼`).join('、')||'无';}
function summaryStatus(st,automatic=false){const chat=api.chat(),done=coveredFloors(st),hidden=chat.map((m,i)=>m.is_system?i:null).filter(Number.isInteger),range=eligibleRange(chat,st,{...settings,keepRecent:0},automaticStart(store(),settings.autoStartFloor),settings.autoBatchSize),uncovered=chat.map((_,i)=>i).filter(i=>!done.includes(i));return `<section class="smm-progress-board"><h3>${automatic?'自动总结状态':'当前聊天处理进度'}</h3>${!automatic?`<p>已保存总结：${h(intervalLabel(done))}</p><p>已隐藏楼层：${h(intervalLabel(hidden))}</p><p>尚未总结：${h(intervalLabel(uncovered))} ${uncovered.length?btn('ignore-floors','忽略'):''}</p>${st.ignoredFloors?.length?'<p>其中手动忽略：'+h(intervalLabel(st.ignoredFloors))+' '+btn('ignore-reset','取消忽略')+'</p>':''}`:''}${automatic?`<p>下一自动范围：${range?`第${range.start}-${range.end}楼 · ${range.complete?'已达到触发数量':'等待新消息'}`:'暂无可处理范围'}</p><p>当前自动起始楼层：${range?.start??automaticStart(st,settings.autoStartFloor)}楼</p><p>自动总结：${settings.autoSummary?(autoPaused?'已暂停':'已启用'):'未启用'} · 起点 ${automaticStart(st,settings.autoStartFloor)} 楼 · 每次 ${Number(settings.autoBatchSize)||1} 条</p><div class="smm-actions">${btn('auto-toggle',settings.autoSummary&&!autoPaused?'暂停自动总结':'开始自动总结')}${btn('settings-shortcut','自动总结设置')}</div>`:''}<p>当前任务：${h(job?.stage||'空闲')}${batchQueue.length||batchRunning?' · 批量已保存 '+batchLedger.filter(b=>b.status==='saved').length+'/'+batchTotal+' 批':''}</p></section>`;}
function organizationView(memories){const eligible=memories.filter(m=>m.status==='active'&&m.kind!=='fixed'&&!m.imported);return countControls(settings)+`<p class="smm-hint">这里整理已保存记忆；记忆正文仍保存在“记忆”页的同一条记录中。</p>${[1,2,3].map(level=>{const list=memories.filter(m=>(m.level??1)===level);const next=list.filter(m=>m.status==='active'&&m.kind!=='fixed'&&!m.imported);return `<details class="smm-group"><summary>${['','首次总结','二次总结','三次总结'][level]} <small>${list.length}条 · ${summaryLevelLabel(level)}</small></summary>${level<3?`<label class="smm-check"><input type="checkbox" data-org-all="${level}">全选本阶段可合并记忆</label>${next.map(m=>`<details class="smm-memory-details smm-merge-option"><summary><label><input type="checkbox" data-org-pick="${level}" value="${h(m.id)}">${h(m.title)}</label><small>${h(m.rangeLabel||floorLabel(m.sources))} · ${summaryLevelLabel(level)}</small></summary><p>${h(m.summary)}</p></details>`).join('')||'<p>暂无可整理记忆。</p>'}<label>本次整理要求<textarea id="smm-org-temp${level}"></textarea></label>${btn('org-preview'+(level+1),'预览选中材料与提示词')}<div id="smm-org-preview${level+1}"></div>${level===1?btn('org-merge2','生成二次总结'):btn('org-merge3','生成三次总结')}`:list.map(card).join('')||'<p>暂无可整理记忆。</p>'}</details>`;}).join('')}`;}
async function render(){persistSession();if(!panel)return;if(tab==='settings'&&!suppressKeyCapture){for(const [id,target] of [['smm-key',client],['smm-check-key',checkClient],['smm-repair-key',repairClient]]){const el=panel.querySelector('#'+id);if(el)target.key=el.value.trim();}}const selectedBefore=new Set([...panel.querySelectorAll('[data-pick]:checked')].map(e=>e.dataset.pick));const scroll=panel.querySelector('.smm-body').scrollTop;const openDrawers=new Set([...panel.querySelectorAll('details[open]')].map(e=>e.dataset.entry||e.querySelector(':scope > summary')?.textContent));const epoch=++renderEpoch;let st;try{st=store();}catch(e){panel.querySelector('.smm-body').textContent=e.message;return;}panel.querySelector('.smm-status').textContent=`${context().name2||'当前聊天'} · ${api.chat().length}条 · 有效记忆${st.memories.filter(m=>m.status==='active').length}条${job?' · 处理中，可关闭面板':''}`;let body='';if(tab==='settings')body=btn('tour','重新打开新手引导')+settingsView();else if(tab==='summary'){const next=nextFloor(st,settings.startFloor);const r=eligibleRange(api.chat(),st,{...settings,keepRecent:0});body=summaryStatus(st)+'<details class="smm-group smm-request-stats"><summary>本次总结字符数<small>原文、人设、世界书与提示词 · 点击展开／收起</small></summary>'+materialSelectionView()+'<div id="smm-request-usage">'+usageView(requestInfo,lastActual)+'</div>'+btn('usage-preview','更新字符数与请求预览')+'</details>'+btn('summary-refresh','刷新总结状态')+'<div id="smm-summary-state">'+h(job?.stage||'等待选择总结材料')+'</div>'+summaryView(r,Math.max(0,api.chat().length-1),st.memories,{...settings,nextStart:next},selectedBooks());}else if(tab==='draft'){body=draft?`<p>选择范围 ${h(draft.rangeLabel||floorLabel(draft.floors))} · ${draft.items.length}条 · ${summaryLevelLabel(draft.level)} · ${draft.checked?'首版已检查':'尚未检查'}</p>${draft.checked&&!draft.issues.length?'<section class="smm-content">AI检查完成：未报告有依据的问题。</section>':''}${versionsView()}<div class="smm-actions">${classification()}</div>${draft.warnings?.length?'<details class="smm-issues"><summary>本次来源与原话核对提醒 · '+draft.warnings.length+'项</summary>'+draft.warnings.map(h).join('<br>')+'</details>':''}${keywordWarning(draft.items)}${draft.items.map(card).join('')}${globalIssuesView()}${checkRawView()}<div class="smm-actions smm-draft-actions">${!draft.checked&&!draft.savedReview&&!draft.reviewHistory&&!draft.rewritten?btn('check','AI检查'):''}${btn('regenerate','重新生成')}${btn('discard','丢弃草稿')}</div>`:'没有待确认草稿。';}else if(tab==='organize'){body=organizationView(st.memories);}else if(tab==='logs'){body=`<div class="smm-log-switch">${btn('logs-mode-tasks','任务记录')}${btn('logs-mode-memory','向主模型发送记忆')}</div>`+(logsMode==='tasks'?btn('logs-export','导出完整任务日志')+btn('logs-refresh','刷新日志')+btn('logs-delete-old','删除最早100条')+btn('logs-clear','清空任务记录')+'<div id="smm-log-list">'+await taskLogsView()+'</div>':btn('logs-refresh','刷新日志')+btn('logs-export-memory','导出记忆发送记录')+btn('logs-delete-old','删除最早100条发送记录')+btn('logs-clear','清空记忆发送记录')+'<div id="smm-injection-view">'+await memoryLogsView()+'</div>');}else{const list=current().filter(m=>memoryFilter==='archive'?m.status!=='active':m.status==='active');body=`<div class="smm-actions">${btn('scope-chat','本聊天记忆')}${btn('scope-attic','角色共享记忆')}</div><p class="smm-hint">${scope==='attic'?'这里由同角色其他聊天共享，只有你主动放入的内容。':'这里只保存本聊天剧情，与其他聊天隔离。'}</p><div class="smm-actions">${btn('filter-active','有效记忆')}${btn('filter-archive','归档')}${btn('manual','手动新增记忆')}${btn('check-short-all','检查全部短期记忆')}${btn('export','导出本聊天记忆')}${btn('memory-import','导入本聊天记忆')}</div><div class="smm-searchbar"><input id="smm-search" placeholder="搜索正文、约定、物品、关键词"><button data-action="search-start">查找</button><button data-action="search-prev" aria-label="上一条">‹</button><span id="smm-search-count">0/0</span><button data-action="search-next" aria-label="下一条">›</button></div><div class="smm-actions">${classification()}${btn('archive','归档／恢复')}${btn('memory-delete','删除选中记忆')}${scope==='chat'?btn('share','复制到角色阁楼'):''}</div>${keywordWarning(list)}${list.length?['short','long','fixed'].map(kind=>group(({short:'短期记忆',long:'长期记忆',fixed:'固定记忆'}[kind])+' · '+list.filter(m=>m.kind===kind).length+'条',list.filter(m=>m.kind===kind).map(card).join('')||'暂无')).join(''):'暂无记忆，可在总结页生成或手动添加。'}`;}if(!localStorage.getItem(NS+':tour-seen'))body='<aside class="smm-content">第一次使用？'+btn('tour','开始新手引导')+btn('tour-skip','跳过引导')+'</aside>'+body;body=batchReport()+(tab==='draft'?pendingDraftsView():'')+body;if(batchQueue.length)body='<section class="smm-content"><b>待处理批次 '+batchQueue.length+' 批</b><div class="smm-actions">'+btn('batch-next',batchQueue[0]?.failed?'重试失败批':'继续下一批')+btn('batch-skip','跳过当前批')+btn('batch-pause','本次完成后暂停')+btn('batch-cancel','停止后续批次')+'</div></section>'+body;if(epoch!==renderEpoch)return;panel.querySelector('.smm-body').innerHTML=body;for(const e of panel.querySelectorAll('[data-pick]'))e.checked=selectedBefore.has(e.dataset.pick);for(const d of panel.querySelectorAll('details'))if(openDrawers.has(d.dataset.entry||d.querySelector(':scope > summary')?.textContent))d.open=true;panel.querySelector('.smm-body').scrollTop=scroll;const footer=panel.querySelector('.smm-save');footer.hidden=tab!=='settings'&&!(tab==='draft'&&draft);footer.innerHTML=tab==='settings'?btn('settings-save','保存设置'):btn('approve','确认保存')+(pendingDrafts.length?btn('approve-all','保存全部待确认批次'):'');panel.querySelectorAll('[data-tab]').forEach(e=>e.classList.toggle('active',e.dataset.tab===tab));styleButtons();applyAppearance();const autoStatus=panel.querySelector('#smm-auto-status');if(autoStatus)autoStatus.innerHTML=summaryStatus(st,true);const ps=panel.querySelector('#smm-profiles');if(ps)ps.value=selectedProfile;const ks=panel.querySelector('#smm-key-presets');if(ks)ks.value=selectedKeyProfile;}
function versionsView(){return draftVersions.length?group('草稿版本 · '+draftVersions.length+'份','<p>切换后确认保存当前版本。比较变化不代表自动判断质量。</p>'+draftVersions.map((d,i)=>'<details class="smm-content smm-memory-details"><summary>第'+(i+1)+'版 · '+h(d.rangeLabel||floorLabel(d.floors))+'</summary>'+btn('version-select','采用第'+(i+1)+'版',`data-version="${i}"`)+d.items.map(m=>'<h4>'+h(m.title)+' · '+h(summaryLevelLabel(m.level??d.level??1))+'</h4><p>'+h(m.summary)+'</p>').join('')+'</details>').join('')):'';}
function classification(){return btn('kind-short','添加到短期')+btn('kind-long','添加到长期')+btn('kind-fixed','添加到固定');}
function open(){if(!panel){panel=document.createElement('section');panel.id='smm-panel';panel.innerHTML=`<header><strong>酒馆记忆管理器 ${VERSION}</strong><div class="smm-actions">${btn('tour','?', 'title="新手引导" aria-label="新手引导"')}${btn('settings-open','⚙','title="设置" aria-label="设置"')}${btn('window-size','↔','title="调整窗口大小" aria-label="调整窗口大小"')}${btn('window-fit','⛶','title="恢复适配屏幕" aria-label="恢复适配屏幕"')}${btn('minimize','−','title="缩小" aria-label="缩小"')}${btn('close','×','title="关闭面板" aria-label="关闭面板"')}</div></header><div class="smm-status"></div><nav>${['memories','summary','draft','organize','logs'].map((t,i)=>`<button type="button" data-tab="${t}">${['记忆','总结','待确认','记忆整理','日志'][i]}</button>`).join('')}</nav><div class="smm-progress" hidden></div><div class="smm-body"></div><div class="smm-save" role="group" aria-label="确认与保存">${btn('settings-save','保存设置')}</div>`;document.body.append(panel);toggleMinimize=bindPanelMovement(panel);panel.addEventListener('click',e=>{if(e.target.matches('[data-pick],[data-org-pick]')){e.stopPropagation();return;}const tag=e.target.closest('[data-tag-preset]');if(tag){const input=panel.querySelector('[data-setting="'+tag.dataset.tagPreset+'"]');const values=new Set(input.value.split(/[,，\s]+/).filter(Boolean));if(values.has(tag.dataset.tag))values.delete(tag.dataset.tag);else values.add(tag.dataset.tag);input.value=[...values].join(',');return;}const t=e.target.closest('[data-tab],[data-action]');if(!t)return;if(t.dataset.tab){if(tab==='settings'){try{if(!pendingProfileOptions)Object.assign(settings,readSettings());captureKeys();}catch(e){report(e);return;}}tab=t.dataset.tab;render().catch(report);}else action(t.dataset.action,t).catch(report);});panel.addEventListener('change',e=>{const t=e.target;if(t.matches('[data-count-mode],[data-count-value]')){try{readCount();store().options=contentSettings(settings);save().catch(report);}catch(e){report(e);}}previewAppearance(t);if(t.dataset.orgAll){for(const x of panel.querySelectorAll('[data-org-pick="'+t.dataset.orgAll+'"]'))x.checked=t.checked;}if(t.dataset.reference){settings[t.dataset.reference]=t.checked;store().options=contentSettings(settings);save().catch(report);requestInfo=null;updateUsage();}if(t.dataset.book){settings.booksByCharacter??={};settings.booksByCharacter[characterKey()]=[...panel.querySelectorAll('[data-book]:checked')].map(e=>e.dataset.book);globalSettings.booksByCharacter=structuredClone(settings.booksByCharacter);saveSettings();requestInfo=null;updateUsage();}if(t.id==='smm-profiles'&&t.value)action('profile-load',t).catch(report);if(t.dataset.mode){const wrap=panel.querySelector('[data-send-wrap='+t.dataset.mode+']');if(wrap)wrap.hidden=t.value!=='separate';}if(['shortPrompt','longPrompt','tertiaryPrompt'].includes(t.dataset.setting))panel.querySelector('[data-setting=promptVariant]').value='custom';if(t.dataset.setting==='filterMode'){const tags=panel.querySelector('[data-filter-tags]');if(tags)tags.hidden=t.value==='off';}if(t.dataset.setting==='repairSeparate')panel.querySelector('[data-connection=repair]').hidden=!t.checked;if(t.id==='smm-repair-models'&&t.value)panel.querySelector('[data-setting=repairModel]').value=t.value;if(t.dataset.setting==='checkSeparate')panel.querySelector('[data-connection=check]').hidden=!t.checked;if(t.id==='smm-check-models'&&t.value)panel.querySelector('[data-setting=checkModel]').value=t.value;if(t.id==='smm-models'&&t.value)panel.querySelector('[data-setting="model"]').value=t.value;if(t.dataset.lock){const m=(tab==='draft'?draft.items:current()).find(m=>m.id===t.dataset.lock);if(m){m.locked=t.checked;if(tab!=='draft'){save().catch(report);saveSettings();}}}});panel.addEventListener('input',e=>{previewAppearance(e.target);if(['smm-start','smm-end','smm-temp'].includes(e.target.id)){const usage=panel.querySelector('#smm-request-usage');if(usage)usage.innerHTML='<p>范围或要求已修改，点击“更新用量与请求预览”重算；尚未发送。</p>';}if(e.target.dataset.mergeSearch){const level=e.target.dataset.mergeSearch,q=e.target.value.toLowerCase();for(const option of panel.querySelectorAll('[data-merge-option="'+level+'"]'))option.hidden=!option.textContent.toLowerCase().includes(q);}});}panel.hidden=false;toggleMinimize?.fit();render().catch(report);}
function progress(text){taskProgress.update(text&&activeBatch&&!/^第\d+\//.test(text)?'第'+activeBatch.ordinal+'/'+batchTotal+'批 · 第'+activeBatch.start+'-'+activeBatch.end+'楼 · '+text:text,settings.showProgress!==false,batchQueue.length>0);}
function readSettings(){const next=Object.assign(structuredClone(settings),pendingProfileOptions||{},appearanceDraft||{});if(panel.querySelector('[data-appearance]'))next.appearance=readAppearance(panel,next.appearance);for(const e of panel.querySelectorAll('[data-setting]'))next[e.dataset.setting]=e.type==='checkbox'?e.checked:e.hasAttribute('data-numeric')?(e.value===''?'':Number(e.value)):e.value;for(const e of panel.querySelectorAll('[data-stage-rules]')){next.stageRules??=[];next.stageRules[Number(e.dataset.stageRules)]=e.value;}for(const e of panel.querySelectorAll('[data-setting^="phasePriority."]')){next.phasePriority??={};next.phasePriority[e.dataset.setting.split('.')[1]]=e.value;delete next[e.dataset.setting];}for(const e of panel.querySelectorAll('[data-mode]'))next.modes[e.dataset.mode]=e.value;for(const entry of next.promptEntries||[]){const name=panel.querySelector('[data-entry-name=\"'+entry.id+'\"]');const content=panel.querySelector('[data-entry-content=\"'+entry.id+'\"]');const enabled=panel.querySelector('[data-entry-enabled=\"'+entry.id+'\"]');if(name)entry.name=name.value;if(content)entry.content=content.value;if(enabled)entry.enabled=enabled.checked;}if(panel.querySelector('[data-batch-manual]'))next.batchManualKinds=[...panel.querySelectorAll('[data-batch-manual]:checked')].map(e=>e.dataset.batchManual);for(const e of panel.querySelectorAll('[data-send]'))next.sendFields[e.dataset.send]=e.checked;if(panel.querySelector('#smm-books'))next.worldBooks=[...panel.querySelectorAll('[data-book]:checked')].map(e=>e.dataset.book);for(const [key,min,max] of [['autoStartFloor',0,1000000],['autoBatchSize',1,10000],['keywordMin',1,100],['keywordWindow',0,100],['retries',0,3],['timeout',10,3600],['keepRecent',0,100000],['batchSize',1,10000],['secondaryCount',2,1000],['tertiaryCount',2,1000],['shortRounds',0,20],['excerptLength',0,1000],['startFloor',0,1000000]])if(!Number.isInteger(next[key])||next[key]<min||next[key]>max)throw Error(key+'需为'+min+'～'+max+'整数');if(next.outputTokens!==''&&next.outputTokens!==undefined&&(!Number.isInteger(next.outputTokens)||next.outputTokens<1))throw Error('输出token上限需为正整数或留空');if(next.budget!==''&&(!Number.isInteger(next.budget)||next.budget<1))throw Error('字符上限需为正整数或留空');if(!['off','combined'].includes(next.filterMode))throw Error('筛选模式无效');for(const v of Object.values(next.modes))if(!['inline','separate','off'].includes(v))throw Error('总结栏目设置无效');if(!['any','all','min'].includes(next.keywordRule))throw Error('关键词规则无效');if(next.baseUrl&&!['http:','https:'].includes(new URL(next.baseUrl).protocol))throw Error('地址格式不正确');return next;}
async function begin(label,work,independent=false){if(!independent&&settings.pluginEnabled===false)throw Error('插件已关闭，请在设置顶部开启');if(job||committing)throw Error('已有任务或保存操作运行中');const initialChat=chatKey();if(!independent&&await isMainGenerating())throw Error('主模型确实正在生成，请结束后再总结');if(initialChat!==chatKey())throw Error('聊天已切换，请重新操作');if(job||committing)throw Error('已有任务运行中');job={id:crypto.randomUUID(),chat:chatKey(),stage:label,started:Date.now(),controller:new AbortController()};const j=job;let ticker;if(independent)notify(label);else{taskProgress.reset();progress(label);ticker=setInterval(()=>progress(j.stage+' · 总计'+Math.floor((Date.now()-j.started)/1000)+'秒'),1000);}try{return await work(j);}catch(error){await log(error.name==='AbortError'?'任务取消':'任务失败',{message:error.message,elapsedMs:Date.now()-j.started});throw error;}finally{clearInterval(ticker);if(job===j)job=null;if(!independent)progress('');}}

function assertJob(j){if(j.controller.signal.aborted||j.chat!==chatKey())throw Error('任务取消或聊天已切换，未写入');}
function memorySources(parents){return parents.map(m=>({floor:m.sources[0],role:'memory',memoryId:m.id,originalFloors:m.sources,text:m.summary+'\n'+JSON.stringify(m.details),quotes:(m.quoteChecks||[]).filter(q=>q.verified)}));}
function buildMessages(sources,refs,temporary='',parents=false,level=1){return buildSummaryMessages({...settings,batchProcessing:batchProcessing||requestedKind==='long'},sources,refs,countInstruction(settings.memoryCountMode,settings.memoryCount)+'\n'+temporary+(requestedKind==='long'?'\n本次保存为长期记忆，必须提供 brief 和 keywords；不改变事实提取范围。':''),parents,level);}
function materialSelectionView(){return help('资料选择与字符数说明','勾选的资料才计入字符数并发送。原文由下方楼层范围决定，不裁剪。',true)+[['includeCharacter','角色人设'],['includeWorldBooks','角色世界书'],['includeMemories','已有记忆']].map(([k,label])=>'<label class="smm-check"><input type="checkbox" data-reference="'+k+'" '+(settings[k]?'checked':'')+'>'+label+'</label>').join('')+btn('books','读取角色绑定世界书')+'<div id="smm-books">'+selectedBooks().map(n=>'<label class="smm-check"><input type="checkbox" data-book="'+h(n)+'" checked>'+h(n)+'</label>').join('')+'</div>';}
function updateUsage(){const e=panel?.querySelector('#smm-request-usage');if(e)e.innerHTML=usageView(requestInfo,lastActual);}
function injectionView(){if(!lastInjection)return '<p>本页面尚无发送记录。以下显示最近一次准备注入，完整历史在调用日志。</p>';return group('最近一次发送记忆',`<p>${lastInjection.observed?'已观察到主请求组装事件；后续扩展仍可能修改。':'已准备注入，尚未观察到最终请求组装。'}</p>${lastInjection.included.map(m=>'<article class="smm-card"><b>'+h(m.title)+' · '+h(summaryLevelLabel(m.level??1))+'</b><p>'+h(m.mode==='brief'?'短版':'详细版')+' · '+h(m.reason)+' · 来源 '+h(floorLabel(m.sources))+'</p></article>').join('')}<h4>插件准备注入的完整文本</h4><pre>${h(lastInjection.text||'未注入任何记忆')}</pre><h4>未发送</h4><pre>${h(JSON.stringify(lastInjection.excluded,null,2))}</pre>`);}
async function logsView(){const list=(await records('logs')).filter(x=>x.chat===chatKey()).sort((a,b)=>b.created-a.created);return '<p class="smm-log-count">当前聊天 '+list.length+' 条日志 · 数据正文约 '+(new Blob([JSON.stringify(list)]).size/1048576).toFixed(2)+' MB（不含数据库索引及备份）</p>'+list.slice(0,100).map((x,i)=>group(`第${list.length-i}条 · ${h(x.stage)} · ${h(new Date(x.created).toLocaleTimeString())}`,btn('log-copy','复制',`class="smm-copy" title="复制本条日志" data-log-id="${h(x.id)}"`)+`<pre>${h(JSON.stringify(x.data,null,2))}</pre>`)).join('');}
async function taskLogsView(){const list=(await records('logs')).filter(x=>x.chat===chatKey()&&x.channel!=='memory'&&!/请求组装观察|文本请求组装观察|主模型记忆准备/.test(x.stage)).sort((a,b)=>b.created-a.created),tasks=new Map();for(const row of list){const id=row.task||'taskless';if(!tasks.has(id))tasks.set(id,[]);tasks.get(id).push(row);}return '<p class="smm-log-count">'+list.length+' 个过程记录，按任务收纳；完整材料按需展开。</p>'+[...tasks.entries()].slice(0,100).map(([id,rows])=>{const first=rows.at(-1),last=rows[0],scope=rows.find(x=>x.stage==='任务范围'),label=scope?'总结任务 · '+summaryLevelLabel(scope.data.level):first.stage;const floors=rows.find(x=>x.stage==='总结输入')?.data?.sources?.flatMap(s=>s.originalFloors||[s.floor])||[];const body=rows.map(x=>`<details class="smm-log-event ${x.important?'smm-log-important':''}"><summary>${x.important?'★ ':''}${h(x.stage)} · ${h(new Date(x.created).toLocaleTimeString())}</summary>${btn('log-copy','复制',`class="smm-copy" data-log-id="${h(x.id)}"`)}<pre>${h(JSON.stringify(x.data,null,2))}</pre></details>`).join('');const status=rows.some(x=>/任务失败|批次失败/.test(x.stage))?'失败／需处理':rows.some(x=>x.stage==='确认保存')?'成功·已保存':rows.some(x=>x.stage==='检查失败但草稿保留')?'生成成功·检查失败':rows.some(x=>x.stage==='草稿展示就绪')?'成功·待确认':rows.some(x=>x.stage==='API错误')?'连接失败':rows.some(x=>x.stage==='任务取消')?'已取消':'处理中／历史未记结果';return group(`<strong class="smm-task-result">${h(status)}</strong> · ${h(label)} · ${h(scope?.data.range||(floors.length?floorLabel(floors):'附属事件'))} · ${rows.length}步 · ${h(new Date(first.created).toLocaleTimeString())}`,`<p>${h(id==='taskless'?'附属事件':id)} · 最近：${h(last.stage)}</p>${body}`);}).join('');}
async function memoryLogsView(){const list=(await records('logs')).filter(x=>x.chat===chatKey()&&(x.channel==='memory'||x.stage==='主模型记忆准备')).sort((a,b)=>b.created-a.created);return '<p class="smm-log-count">只记录插件准备注入的记忆，不包含主模型人设、预设或其他上下文。</p>'+list.slice(0,100).map(x=>group(`★ ${x.data.included.length} 条记忆 · ${h(new Date(x.created).toLocaleString())}`,`${btn('log-copy','复制',`class="smm-copy" data-log-id="${h(x.id)}"`)}${x.data.observed?'<p>观察到请求组装事件；后续扩展仍可能修改。</p>':'<p>插件准备注入，尚未观察到最终请求组装。</p>'}${x.data.included.map(m=>`<details class="smm-memory-details"><summary>${h(m.title)} · ${h(({short:'短期',long:'长期',fixed:'固定'})[m.kind]||m.kind)} · ${summaryLevelLabel(m.level)}</summary><p>${h(m.summary)}</p><small>来源 ${h(m.rangeLabel||floorLabel(m.range||m.sources))} · ${h(m.reason||'')}</small></details>`).join('')||'<p>本轮没有符合条件的记忆。</p>'}<details><summary>插件准备注入的记忆文本</summary><pre>${h(x.data.text||'无')}</pre></details>`)).join('')||'<p>暂无主模型记忆发送记录。</p>';}
async function previewRequest(start,end,temporary='',parents=null,target='#smm-prompt-preview',level=1){readCount();const chat=chatKey();const sources=parents?memorySources(parents):sourceSnapshot(api.chat(),start,end,settings);const refs=await references([...(parents?.map(m=>m.id)||[]),...(draft?.regenerating?draft.items.map(m=>m.id):[])]);if(chat!==chatKey())throw Error('聊天已切换，未显示旧预览');const messages=buildMessages(sources,refs,temporary,!!parents,level);requestInfo=requestBreakdown(messages);lastActual=null;updateUsage();const e=panel?.querySelector(target);if(e)e.innerHTML=requestView(messages);}
async function references(excludeIds=[]){const c=context(),ch=c.characters?.[c.characterId];return {character:settings.includeCharacter?{name:ch?.name,description:ch?.description||ch?.data?.description,personality:ch?.personality||ch?.data?.personality,scenario:ch?.scenario||ch?.data?.scenario}:null,memories:settings.includeMemories?all().filter(m=>m.status==='active'&&!excludeIds.includes(m.id)).map(m=>({id:m.id,kind:m.kind,level:m.level??1,summary:m.summary,details:m.details})):[],worldBooks:settings.includeWorldBooks?(await worldBooks(selectedBooks())).books:[]};}

function stage(j,text){assertJob(j);j.stage=text;progress(text+' · 总计'+Math.floor((Date.now()-j.started)/1000)+'秒');const e=panel?.querySelector('#smm-summary-state');if(e)e.textContent=text;void log('阶段',{stage:text,at:new Date().toISOString(),elapsedMs:Date.now()-j.started}).catch(()=>{});}
async function summarize(start,end,temporary='',parents=null,level=1,hideAfter=settings.autoHide,sourceOverride=null){readCount();let result;let preservedDraft=null;if(draft&&!draft.regenerating&&!batchProcessing){const choice=await choiceDialog('已有待确认草稿',[['view','查看已有草稿'],['new','保留已有草稿，重新总结']]);if(choice!=='new'){if(choice==='view'){tab='draft';await render();}return;}preservedDraft=structuredClone(draft);}if(!batchProcessing&&!draft?.regenerating&&!preservedDraft)draftVersions=[];await begin('正在总结；可以关闭面板',async j=>{await log('任务范围',{range:parents?intervalLabel(parents.flatMap(p=>p.selectedFloors||p.sources)):`第${start}-${end}楼`,level,batch:activeBatch?.ordinal,total:batchTotal});const taskSettings={...structuredClone(settings),summaryLevel:level,batchProcessing:batchProcessing||requestedKind==='long',allowSourceMismatch:true};let sources=sourceOverride?structuredClone(sourceOverride):parents?memorySources(parents):sourceSnapshot(api.chat(),start,end,settings);if(!sources.length)throw Error('没有可处理消息');const missing=sources.filter(s=>s.missing||!s.text.trim());if(missing.length){if(!confirm('第 '+missing.map(s=>s.floor).join('、')+' 层未提取到正文（可能缺少白名单标签或正文为空）。继续将跳过这些楼层，只总结其余内容。是否继续？'))return;sources=sources.filter(s=>s.text.trim()&&!s.missing);}if(!sources.length)throw Error('所选楼层均未提取到正文，请调整筛选或范围');stage(j,'整理材料与请求预览');await log('任务范围',{parentTask:draft?.regenerating?draft.taskId:null,action:sourceOverride?'重新生成':batchProcessing?'批量总结':automaticTask?'自动总结':parents?'记忆整理':'手动总结',range:parents?intervalLabel(parents.flatMap(p=>p.selectedFloors||p.sources)):`第${start}-${end}楼`,level});const refs=await references([...(parents?.map(m=>m.id)||[]),...(draft?.regenerating?draft.items.map(m=>m.id):[])]);assertJob(j);const messages=buildMessages(sources,refs,temporary,!!parents,level);requestInfo=requestBreakdown(messages);lastActual=null;updateUsage();await log('总结输入',{sources,refs,messages,level,effectiveCheck:taskSettings.check,usage:requestInfo.counts,outputMode:settings.outputMode||'json',formatRepair:taskSettings.formatRepair,repairConnection:taskSettings.repairSeparate?'独立格式修复连接':'总结连接'});stage(j,'等待总结模型返回');let raw=await client.request('summary',messages,j.controller.signal);lastActual=client.lastUsage;updateUsage();assertJob(j);await log('总结模型返回',{raw,range:`第${start}-${end}楼`,level});stage(j,'解析与校验总结结果');let items;try{items=validateDraft(raw,sources,taskSettings);await log('解析通过',{outputMode:settings.outputMode||'json',count:items.length});}catch(error){await log('解析失败',{outputMode:settings.outputMode||'json',message:error.message,raw});if(!taskSettings.formatRepair||error.message.includes('[来源校验]')){await log('未调用格式修复',{enabled:!!taskSettings.formatRepair,reason:!taskSettings.formatRepair?'用户未开启格式失败修复':'来源问题不进行格式修复'});throw error;}stage(j,'格式失败：正在修复一次');const repair=repairMessages(raw,error,taskSettings);await log('格式修复输入',{messages:repair});const repaired=await (taskSettings.repairSeparate?repairClient:client).request('repair',repair,j.controller.signal);assertJob(j);stage(j,'校验格式修复结果');try{items=validateDraft(repaired,sources,taskSettings);}catch(e){await log('格式修复失败',{message:e.message,raw:repaired});throw Error('格式修复后仍未通过：'+e.message+'。原始回复与修复回复均已保留');}raw=repaired;await log('格式修复通过',{count:items.length});}for(const m of items){m.rangeLabel=parents?intervalLabel(parents.flatMap(p=>p.selectedFloors||p.sources)):`第${start}-${end}楼`;m.selectedFloors=parents?[...new Set(parents.flatMap(p=>p.selectedFloors||p.sources))]:Array.from({length:end-start+1},(_,i)=>start+i);m.level=level;m.brief=level===1&&!taskSettings.batchProcessing?'':m.brief;m.keywords=level===1&&!taskSettings.batchProcessing?[]:m.keywords;m.originChat=chatKey();if(parents)m.parentIds=parents.map(p=>p.id);}if(preservedDraft&&!draftVersions.some(v=>v.versionId===preservedDraft.versionId))draftVersions.push(preservedDraft);const generated={batchOrdinal:activeBatch?.ordinal||null,baseRevision:store().revision,versionId:crypto.randomUUID(),taskId:j.id,rangeLabel:items[0].rangeLabel,items,sources,refs,temporary,floors:parents?[...new Set(parents.flatMap(m=>m.sources))]:sources.map(s=>s.floor),level,hideAfter,parents:parents?.map(m=>m.id)||[],issues:[],checked:false,chat:chatKey()};if(!batchProcessing)draft=generated;if(level>=2){generated.items.forEach(m=>m.kind=level===2?'long':taskSettings.tertiaryDefaultKind||'fixed');const kind=await choiceDialog((level===2?'二次':'三次')+'总结已完成，建议添加到长期记忆',[...(level===2?['long','short','fixed']:[settings.tertiaryDefaultKind||'fixed',settings.tertiaryDefaultKind==='long'?'fixed':'long']).map(k=>[k,'添加到'+(k==='fixed'?'固定':k==='long'?'长期':'短期')+'记忆'+(k===(level===2?'long':settings.tertiaryDefaultKind||'fixed')?'（默认）':'')]),['later','稍后在待确认中选择']]);assertJob(j);if(['fixed','long','short'].includes(kind))generated.items.forEach(m=>m.kind=kind);}if(preservedDraft)draftVersions.push(structuredClone(generated));const warnings=items.flatMap(m=>m.validationWarnings||[]),quotes=items.flatMap(m=>m.quoteChecks||[]).filter(q=>!q.verified);generated.warnings=[...(settings.memoryCountMode==='single'&&items.length!==1||settings.memoryCountMode==='count'&&items.length!==Number(settings.memoryCount)?['模型返回条数与所选策略不符，已保留全部'+items.length+'条，请核对。']:[]),...new Set(warnings),...(quotes.length?[`${quotes.length}条原话未通过角色回复逐字核对，已集中列为待核对且不发送`]:[])];await log('总结草稿',{draft:generated});if(taskSettings.check===true&&!sourceOverride){try{await checkDraft(j,generated);}catch(e){assertJob(j);await log('检查失败但草稿保留',{message:e.message});notify('总结草稿已保留，AI检查失败：'+e.message,true);}}assertJob(j);await log('草稿展示就绪',{elapsedMs:Date.now()-j.started});result=generated;if(!batchProcessing){tab='draft';open();notify('总结完成，请核对后保存');}});return result;}
async function checkDraft(j,d=draft){
 stage(j,'AI检查事实与冲突');if(!d)throw Error('没有草稿');
 const messages=[{role:'system',content:settings.checkPrompt+'\n'+priorityInstruction(settings,d.level,true)+'\n【核对优先级】本阶段直接剧情材料用于证明事件发生与否；按上方资料优先级核对约束。重点核对时间地点，区分背景年表、回忆、计划与当前事件，区分目的地与已抵达地点。剧情与设定不一致时报告冲突并引用依据，不能删除真实剧情或自行修正。旧总结仅作参考。意见不得混入记忆正文。优先使用条目真实ID；若写的是summary或details.time等字段位置，插件会作为全局检查意见显示。'},{role:'user',content:JSON.stringify({sources:d.sources,reference:d.refs,draft:d.items})}];
 await log('检查输入',{messages,connection:settings.checkSeparate?'独立检查API':'沿用总结API'});
 const target=settings.checkSeparate?checkClient:client;let raw,originalRaw;
 try{
  raw=await target.request('check',messages,j.controller.signal);originalRaw=raw;assertJob(j);
  const result=parseJson(raw);d.issues=normalizeIssues(result.issues,d.items);
 }catch(error){
  await log('检查解析失败',{message:String(error.message||error),raw:raw||null});
  if(!raw||!settings.formatRepair)throw error;
  stage(j,'检查格式失败：正在修复一次');
  const repair=checkRepairMessages(raw,error,settings);await log('检查格式修复输入',{messages:repair});
  const repaired=await (settings.repairSeparate?repairClient:target).request('repair',repair,j.controller.signal);assertJob(j);
  try{const result=parseJson(repaired);d.issues=normalizeIssues(result.issues,d.items);originalRaw=raw;raw=repaired;d.checkRepairRaw=repaired;await log('检查格式修复通过',{issues:d.issues});}
  catch(e){await log('检查格式修复失败',{message:String(e.message||e),raw:repaired});throw Error('AI检查格式修复后仍未通过：'+e.message+'。原始检查回复与修复回复均已保留');}
 }
 d.checkRaw=originalRaw||raw;d.checked=true;await log('AI检查返回',{raw:d.checkRaw,issues:d.issues});await log('检查结果',{issues:d.issues});
}

async function approve(){if(committing)throw Error('正在保存，请勿重复确认');committing=true;saveCompletion=new Promise(resolve=>{releaseSave=resolve;});try{return await approveInternal();}finally{committing=false;releaseSave?.();releaseSave=null;activeLogTask=null;if(!draft&&!pendingDrafts.length&&!job&&!batchQueue.length&&!batchRunning){if(!automaticTask)setTimeout(()=>maybeAutoMerge().then(()=>runAutomatic()).catch(report),0);}}}
async function approveInternal(){if(context().groupId)throw Error('初版暂不支持群聊保存');if(!draft||draft.chat!==chatKey())throw Error('草稿不属于当前聊天');if(job&&!batchRunning||await isMainGenerating())throw Error('任务运行时不能保存');progress(draft.batchOrdinal?'第'+draft.batchOrdinal+'/'+batchTotal+'批 · 正在保存':'正在保存记忆');const d=draft;if(d.baseRevision!==undefined&&d.baseRevision!==store().revision)throw Error('记忆已被其他操作更新，请重新核对当前草稿');if(!d.savedReview&&store().batches.some(b=>(b.ids||[]).some(id=>d.items.some(m=>m.id===id))))throw Error('这份草稿已经保存，禁止重复添加');if(d.level===1&&!d.savedReview&&d.sources.some(source=>source.raw!==undefined&&api.chat()[source.floor]?.mes!==source.raw))throw Error('原文已变化，请重新总结；草稿仍保留');activeLogTask=d.taskId||null;const st=store();const parents=st.memories.filter(m=>d.parents.includes(m.id));if(parents.some(m=>m.locked)&&!confirm('旧版含保留条目，请确认新稿已完整覆盖，否则取消修改。'))return;const policy=d.level===2?settings.oldPolicy2:settings.oldPolicy3;if(d.level>1&&policy!=='archive'&&!confirm('确认清除旧总结正文？新版本及来源继续保留。'))return;await backup('确认保存前');if(d.chat!==chatKey()||draft!==d)throw Error('确认期间聊天或草稿已改变');const previous=structuredClone(st),previousStart=settings.startFloor,previousAutoStart=settings.autoStartFloor;for(const m of parents){m.status='archived';if(policy!=='archive'){m.summary='';m.brief='';m.details={};m.excerpt='';m.keywords=[];m.status='index';}}if(d.level>1&&policy==='delete')st.memories=st.memories.filter(m=>!d.parents.includes(m.id));if(d.savedReview){for(const item of d.items){const dest=all().find(m=>m.id===item.id);if(dest)Object.assign(dest,structuredClone(item));}saveSettings();}else st.memories.push(...structuredClone(d.items));if(!d.savedReview)st.batches.push({rangeLabel:d.rangeLabel,selectedFloors:d.items[0]?.selectedFloors||d.floors,id:crypto.randomUUID(),level:d.level,parentIds:d.parents||[],approved:true,hideAfter:!!d.hideAfter,floors:d.floors,ids:d.items.map(m=>m.id),created:Date.now()});st.revision++;if(d.level===1&&!d.savedReview){const next=Math.max(...(d.items[0]?.selectedFloors||d.floors))+1;settings.startFloor=Math.max(Number(settings.startFloor)||0,next);settings.autoStartFloor=Math.max(Number(settings.autoStartFloor)||0,next);st.options=contentSettings(settings);}try{await save(d.hideAfter);}catch(e){if(d.chat===chatKey()){context().chatMetadata[NS]=previous;settings.startFloor=previousStart;settings.autoStartFloor=previousAutoStart;}throw e;}await log('确认保存',{items:d.items,parents:d.parents,policy});if(d.batchOrdinal){const row=batchLedger.find(b=>b.ordinal===d.batchOrdinal);if(row)row.status='saved';}persistSession();if(d.chat!==chatKey())throw Error('聊天已切换，保存已结束，未继续隐藏');draft=null;draftVersions=[];progress('');if(d.hideAfter){progress(d.batchOrdinal?'第'+d.batchOrdinal+'/'+batchTotal+'批 · 正在隐藏已保存楼层':'正在隐藏已保存楼层');if(d.level===1)for(const source of d.sources)if(api.chat()[source.floor]?.mes!==source.raw)throw Error('记忆已保存，但原文已变化；未继续隐藏');const floors=(d.level===1?pendingHideFloors(st.batches,d.floors,settings.keepRecent):hideFloors(d.floors,settings.keepRecent)).filter(f=>api.chat()[f]);for(const f of floors){if(d.chat!==chatKey())throw Error('聊天已切换，已停止隐藏');if(!api.chat()[f].is_system){await nativeHide(f,f,false);if(!api.chat()[f]?.is_system)throw Error('记忆已保存，但第'+f+'楼隐藏未生效，已停止后续隐藏');if(!st.hidden.includes(f))st.hidden.push(f);}}await save();await log('原生隐藏完成',{floors});}for(const entry of pendingDrafts){if(entry.draft.baseRevision===previous.revision)entry.draft.baseRevision=st.revision;for(const v of entry.versions||[])if(v.baseRevision===previous.revision)v.baseRevision=st.revision;}restorePendingDraft();progress('');tab=draft?'draft':'memories';memoryFilter='active';if(!d.savedReview)scope='chat';await render();notify('记忆已保存'+(d.hideAfter?'，已处理原文隐藏（保留最近消息）':''));}

async function maybeAutoMerge(){if(settings.pluginEnabled===false||pendingDrafts.length||autoPaused||autoMergeRunning||job||draft||committing||batchRunning||batchQueue.length||!context().chatId)return;const merge=automaticMerge(store().memories,store().batches,settings);if(!merge)return;const origin=chatKey();autoMergeRunning=true;try{notify('已达到数量，开始'+summaryLevelLabel(merge.level)+'；生成后仍需确认');if(origin!==chatKey())return;await summarize(0,0,'',merge.parents,merge.level,settings.autoHide);}finally{autoMergeRunning=false;}}

