 if(name.startsWith('key-preset-')){captureKeys();const id=panel.querySelector('#smm-key-presets').value,p=keyProfiles.find(x=>x.id===id);if(name==='key-preset-load'){if(!p)throw Error('请先选择预设');Object.assign(settings,p.connection);client.key=p.keys.summary;checkClient.key=p.keys.check;repairClient.key=p.keys.repair;selectedKeyProfile=id;keyStore(true);}else if(name==='key-preset-delete'){if(!p)throw Error('请先选择预设');if(!confirm('删除此浏览器中的密钥预设？'))return;keyProfiles.splice(keyProfiles.indexOf(p),1);selectedKeyProfile='';saveKeyProfiles();}else{Object.assign(settings,readSettings());const connection=Object.fromEntries(['baseUrl','model','checkSeparate','checkBaseUrl','checkModel','repairSeparate','repairBaseUrl','repairModel'].map(k=>[k,settings[k]])),keys={summary:client.key,check:checkClient.key,repair:repairClient.key};if(name==='key-preset-update'){if(!p)throw Error('请先选择预设');Object.assign(p,{connection,keys});}else{const name=await textDialog('新增密钥预设','预设名称');if(!name?.trim())return;const v={id:crypto.randomUUID(),name:name.trim(),connection,keys};keyProfiles.push(v);selectedKeyProfile=v.id;}saveKeyProfiles();}suppressKeyCapture=true;try{await render();}finally{suppressKeyCapture=false;}notify('密钥预设已处理，仅存本浏览器');return;}
 if(name==='view-logs'){tab='logs';await render();return;}
 if(name==='view-backups'){const list=(await records('snapshots')).filter(x=>x.chat===chatKey()).sort((a,b)=>b.created-a.created);panel.querySelector('#smm-backup-list').innerHTML=list.length?list.map((x,i)=>'<details class="smm-group"><summary>第'+(list.length-i)+'份备份 · '+h(x.reason)+'</summary>'+btn('restore-selected','恢复这份备份',`data-backup-id="${h(x.id)}"`)+'<pre>'+h(JSON.stringify(x.store,null,2))+'</pre></details>').join(''):'暂无本机备份';return;}
 if(name==='prompt-reset'&&confirm('恢复基础总结与检查提示词？')){settings.basePrompt=DEFAULTS.basePrompt;settings.checkPrompt=DEFAULTS.checkPrompt;settings.promptVariant='original';for(const k of ['shortPrompt','longPrompt','tertiaryPrompt','stageRules'])settings[k]=structuredClone(DEFAULTS[k]);await render();notify('已恢复内置规则，请保存设置');}
