async function inject(type,options,dryRun){api.prompt.clear();pending=null;if(dryRun||['quiet','impersonate'].includes(type)||settings.pluginEnabled===false||!settings.enabled||!context().chatId)return;const st=store(),turn=api.chat().filter(m=>!m.is_user).length,text=api.chat().filter(m=>!m.is_system).slice(Number(settings.keywordWindow??4)===0?api.chat().length:-Number(settings.keywordWindow??4)).map(m=>m.mes).join(' ')+' '+String(document.querySelector('#send_textarea')?.value||'');const selected=selectMemories(all(),text,st.recall,turn,settings),built=buildInjection(selected,settings);api.prompt.set(built.text);pending={chat:chatKey(),included:built.included,turn};lastInjection={text:built.text,included:built.included.map(m=>({id:m.id,title:m.title,mode:m.mode,reason:m.reason,hits:m.hits,sources:m.sources,level:m.level??1})),excluded:built.excluded};const signature=JSON.stringify({chat:chatKey(),turn,type,text:built.text});if(lastInjectionSignature===signature)return;lastInjectionSignature=signature;pending.logId=await log('主模型记忆准备',{type,text:built.text,included:built.included.map(m=>({id:m.id,title:m.title,summary:m.mode==='brief'?m.brief:m.summary,kind:m.kind,level:m.level,rangeLabel:m.rangeLabel,sources:m.sources,mode:m.mode,hits:m.hits,reason:m.reason})),excluded:built.excluded,candidates:all().map(m=>({id:m.id,status:m.status,kind:m.kind,selected:built.included.some(i=>i.id===m.id)}))});}
function bind(){const c=context();const on=(name,fn)=>{if(c.eventTypes[name])api.events.on(c.eventTypes[name],fn);};on('GENERATION_AFTER_COMMANDS',(...args)=>inject(...args).catch(report));on('GENERATION_STARTED',(_type,_options,dryRun)=>{if(!dryRun)generating=true;});on('GENERATION_ENDED',()=>{generating=false;});on('GENERATION_STOPPED',()=>{generating=false;pending=null;});on('CHAT_CHANGED',()=>{document.querySelectorAll('.smm-editor').forEach(d=>d.close('cancel'));scope='chat';batchQueue=[];appearanceDraft=null;pendingProfileOptions=null;selectedProfile='';searchHits=[];draftVersions=[];loadChatSettings();generating=false;job?.controller.abort();client.cancel();checkClient.cancel();repairClient.cancel();requestInfo=null;lastActual=null;lastInjection=null;lastInjectionSignature='';batchTotal=0;batchLedger=[];pendingDrafts=[];activeBatch=null;autoPaused=false;draft=null;pending=null;api.prompt.clear();restoreSession();if(panel&&!panel.hidden)render().catch(report);void historyReminder();});on('CHAT_COMPLETION_PROMPT_READY',async()=>{if(pending&&lastInjection){lastInjection.observed=true;const id=pending.logId;if(id){const row=(await records('logs')).find(x=>x.id===id);if(row){row.data.observed=true;await record('logs',row);}}}});on('MESSAGE_RECEIVED',async()=>{try{generating=false;if(pending?.chat===chatKey()){for(const m of pending.included)if(m.kind==='long'&&m.mode==='full')store().recall[m.id]={until:pending.turn+Number(settings.shortRounds)};await save();pending=null;}await runAutomatic();await maybeAutoMerge();}catch(e){report(e);}});}
restoreSession();
const host=document.querySelector('#extensionsMenu')||document.querySelector('#extensions_settings');
if(!host)throw Error('未找到扩展菜单');
if(!document.getElementById('smm-entry')){const entry=document.createElement('div');entry.id='smm-entry';entry.className='list-group-item flex-container flexGap5 interactable';entry.tabIndex=0;entry.innerHTML='<i class="fa-solid fa-layer-group" aria-hidden="true"></i><span>酒馆记忆管理器</span>';entry.onclick=open;entry.onkeydown=e=>{if(e.key==='Enter')open();};host.append(entry);bind();setTimeout(()=>historyReminder().catch(report),500);window.addEventListener('pagehide',()=>{persistSession();job?.controller.abort();client.cancel();checkClient.cancel();repairClient.cancel();api.prompt.clear();},{once:true});}

